-- PT121-S4-Q14. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT121-S4-Q14$batch11$ AND q.stimulus=$batch11$A new tax law aimed at encouraging the reforestation of cleared land in order to increase the amount of forested land in a particular region offers lumber companies tax incentives for each unit of cleared land they reforest. One lumber company has accordingly reduced its tax liability by purchasing a large tract of cleared land in the region and reforesting it. The company paid for the purchase by clearing a larger tract of land in the region, a tract that it had planned to hold in long-term reserve.$batch11$ AND q.prompt=$batch11$If the statements above are true, which one of the following must be true about the new tax law?$batch11$ AND q.correct_choice=$batch11$D$batch11$) THEN RAISE EXCEPTION 'Question changed: PT121-S4-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT121-S4-Q14$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT121-S4-Q14'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT121-S4-Q14$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$The tax law aims to increase forested land by rewarding companies for reforesting cleared land. One company bought and reforested a cleared tract to cut its taxes. It paid for this by clearing a larger tract it had planned to keep in reserve.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$The company collected the incentive, but cleared more land than it replanted. The law's goal is more forest. The company's actions produced less. So the law can push a company to act against the law's purpose while still getting the tax break.$batch11$), (2, $batch11$Goal$batch11$, $batch11$The law can motivate behavior that works against its own purpose.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT121-S4-Q14$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$One company's case doesn't show the law fails across the region. The company did reforest a tract.$batch11$), ($batch11$B$batch11$, $batch11$The law already had an effect: one tract replanted and a larger one cleared.$batch11$), ($batch11$C$batch11$, $batch11$We have no basis to predict how much land companies will eventually plant.$batch11$), ($batch11$D$batch11$, $batch11$The company took the incentive and still reduced total forest, which works against the law's goal.$batch11$), ($batch11$E$batch11$, $batch11$One company's swap doesn't support a massive decrease in mature forests.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT121-S4-Q14$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
